window.kbPageData["views/entry/k-0a8fc48508a25001"] = {"key":"entry/k-0a8fc48508a25001","state":{"route":"entry/k-0a8fc48508a25001"},"node":{"id":"k-0a8fc48508a25001","mode":"k","title":"为政之要，以顺民心为本","type":"概念与词义","domain":"汉语","reading":"","intro":"","priority":100,"aliases":["“为政之要，以顺民心为本”的含义","“为政之要，以顺民心为本”指治理应以顺应民心为根本"],"qs":["国考 2024 副省级 行测#43","国考 2024 地市级 行测#50","国考 2024 行政执法 行测#53"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":2,"reviewSet":"多题条目","independentCount":1,"directorySummary":"这句话意为治理政事应以顺应民心为根本。","review":{"title":"为政之要，以顺民心为本","type":"概念与词义","definition":"这句话意为治理政事应以顺应民心为根本。","explanation":"“顺”指顺应，“本”指根本。在中央人大工作会议讲话的题选段中，顺应民心体现为听取人民意见、接受人民监督，并通过人大代表联系群众、回应社会关切。","basis":"据关联原题及所列出处编释。","references":[{"source":"quote42","location":"程颐《代吕晦叔应诏疏》与后世引述"}],"related":[],"examFocus":{"国考 2024 副省级 行测#43":"辨析各句古语的侧重点，看哪一句能同时统领后文对国家机关及其工作人员和人大代表的要求。"}},"readings":[{"origin":"k-0a8fc48508a25001","title":"为政之要，以顺民心为本","qs":["国考 2024 副省级 行测#43","国考 2024 地市级 行测#50"],"definition":"这句话意为治理政事应以顺应民心为根本。","explanation":"“顺”指顺应，“本”指根本。在中央人大工作会议讲话的题选段中，顺应民心体现为听取人民意见、接受人民监督，并通过人大代表联系群众、回应社会关切。","evidence":"","doubt":"","references":[{"source":"quote42","location":"程颐《代吕晦叔应诏疏》与后世引述"}]},{"origin":"k-f5eedced27ec9b1f","title":"为政之要，以顺民心为本","qs":["国考 2024 行政执法 行测#53"],"definition":"这句话指治理国家的要务，是把顺应民心作为根本。","explanation":"“为本”指出治理应以什么为根本，与后文所说人民代表大会制度“深深植根于人民之中”相呼应。后文要求国家机关和国家工作人员倾听人民意见、接受人民监督，也要求拓宽人大代表联系群众的渠道，具体说明了这一原则。A项侧重从民众的状况判断治理成效，D项侧重因利民而变革旧制，B项的主旨与后文最贴合。","evidence":"为政之要，以顺民心为本","doubt":"","references":[]}],"aspects":[{"title":"顺应民心与人大联系群众","uses":[{"unit":"Q1","role":"解题依据","use":"本题均选B。文段将人民代表大会制度的生命力归于其植根人民，并提出国家机关及其工作人员听取意见、人大代表联系群众等要求。这句古语概括了以人民为根本的主旨。","evidence":"人民代表大会制度之所以具有强大生命力和显著优越性，关键在于深深植根于人民之中。","qids":["国考 2024 副省级 行测#43","国考 2024 地市级 行测#50"]}]}]},"questions":{"国考 2024 副省级 行测#43":{"paper":"国考 2024 副省级 行测","n":43,"mod":"言语理解与表达","src":["a566fec37e508ca7f975.pdf",7],"asrc":["a475ecf57d968bc14cd6.pdf",14],"card":"53eaf74d023b768729126a7f","links":[{"id":"k-0a8fc48508a25001","role":"解题依据","why":"理解古语中的“顺民心为本”才能判断它是否与后文强调的人民立场一致。"}]},"国考 2024 地市级 行测#50":{"paper":"国考 2024 地市级 行测","n":50,"mod":"言语理解与表达","src":["92d0b72e86a6a33d568d.pdf",9],"asrc":["e1792c53900a45f1b9fa.pdf",15],"card":"89393e64c4c30ac730ddbde3","links":[{"id":"k-0a8fc48508a25001","role":"解题依据","why":"理解“顺民心为本”的含义，才能把这句古语与后文把人民放在首位的主旨对应起来。"}]},"国考 2024 行政执法 行测#53":{"paper":"国考 2024 行政执法 行测","n":53,"mod":"言语理解与表达","src":["dfddc59dc6e7d9da5d71.pdf",9],"asrc":["6493f3a6a55c38431852.pdf",16],"card":"05c9c042a97d2db44bf98aba","links":[{"id":"k-0a8fc48508a25001","role":"解题依据","why":"需要读懂备选古语中的“为本”所表达的根本准则，才能判断其与后文的联系。"}]}},"terms":{},"references":{"quote42":{"name":"《为政之要，以顺民心为本》典故解读","url":"https://gdb.ahsz.gov.cn/xxfb/ztzl/bnzc/195341491.html"}},"topics":[],"units":{"k-0a8fc48508a25001":[["国考 2024 副省级 行测#43","国考 2024 地市级 行测#50","国考 2024 行政执法 行测#53"]]}};
